<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import NxAlert from'../../components/ui/NxAlert.vue';import NxBadge from'../../components/ui/NxBadge.vue';import NxButton from'../../components/ui/NxButton.vue';import NxCard from'../../components/ui/NxCard.vue';import NxModal from'../../components/ui/NxModal.vue';import NxPageHeader from'../../components/ui/NxPageHeader.vue';import NxTableShell from'../../components/ui/NxTableShell.vue';import NxToolbar from'../../components/ui/NxToolbar.vue';import{get,post,type Row}from'./api';
const loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),search=ref(''),statusFilter=ref(''),tickets=ref<Row[]>([]),summary=ref<Row>({}),open=ref(false),ticket=ref<Row>({}),messages=ref<Row[]>([]),users=ref<Row[]>([]),reply=ref(''),note=ref(''),assigned=ref('0'),ticketStatus=ref('OPEN'),priority=ref('MEDIUM');const inputClass='min-h-11 w-full rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface)] px-3 text-sm text-[var(--nx-text)]';
const filtered=computed(()=>{const q=search.value.toLowerCase().trim();return tickets.value.filter(r=>(!statusFilter.value||r.status===statusFilter.value)&&(!q||JSON.stringify(r).toLowerCase().includes(q)));});const fmt=(v:any)=>v?new Date(String(v).replace(' ','T')).toLocaleString('en-PH'):'—';const label=(v:any)=>String(v||'—').replaceAll('_',' ');const tone=(v:any):'success'|'danger'|'warning'|'neutral'=>['RESOLVED','CLOSED','VISIT_SCHEDULED'].includes(String(v).toUpperCase())?'success':['CANCELLED','URGENT'].includes(String(v).toUpperCase())?'danger':['OPEN','IN_PROGRESS','HIGH','WAITING_CUSTOMER','WAITING_TECHNICIAN','WAITING_CUSTOMER_SCHEDULE'].includes(String(v).toUpperCase())?'warning':'neutral';
async function load(show=false){loading.value=true;error.value='';try{const data=await get<any>('/api/v1/tickets?limit=200&offset=0');tickets.value=data?.items||[];summary.value=data?.summary||{};if(show)notice.value='Tickets refreshed.';}catch(e){error.value=e instanceof Error?e.message:'Unable to load tickets.';}finally{loading.value=false;}}
async function show(row:Row){busy.value=true;error.value='';try{const data=await get<any>(`/api/v1/tickets/show/${row.id}`);ticket.value=data?.ticket||{};messages.value=data?.messages||[];users.value=data?.assignable_users||[];assigned.value=String(ticket.value.assigned_user_id||0);ticketStatus.value=String(ticket.value.status||'OPEN');priority.value=String(ticket.value.priority||'MEDIUM');reply.value=note.value='';open.value=true;}catch(e){error.value=e instanceof Error?e.message:'Unable to load ticket details.';}finally{busy.value=false;}}
async function command(url:string,payload:Row,message:string,confirmText=''){if(confirmText&&!confirm(confirmText))return;busy.value=true;error.value='';try{await post(url,{ticket_id:ticket.value.id,...payload});notice.value=message;await load();await show(ticket.value);}catch(e){error.value=e instanceof Error?e.message:'Ticket action failed.';}finally{busy.value=false;}}
async function sendReply(){if(!reply.value.trim())return;const text=reply.value;reply.value='';await command('/api/v1/tickets/reply',{message:text},'Public reply sent.');}async function addNote(){if(!note.value.trim())return;const text=note.value;note.value='';await command('/api/v1/tickets/internal-note',{message:text},'Internal note added.');}async function createWorkOrder(){await command('/api/v1/work-orders/create-from-ticket',{},'Work order created.','Create a work order from this ticket?');}async function requestSchedule(){await command('/api/v1/tickets/request-schedule',{},'Schedule request sent to the subscriber.','Ask the subscriber to select a technician visit schedule?');}
onMounted(()=>void load());
</script>
<template><div class="space-y-4 overflow-x-hidden pb-8 text-[var(--nx-text)]"><NxPageHeader eyebrow="Support operations" title="Support Tickets" description="Manage subscriber concerns, conversations, assignments, scheduling, and workforce handoff."><template #actions><NxButton variant="secondary" :disabled="loading||busy" @click="load(true)">{{loading?'Refreshing…':'Refresh'}}</NxButton></template></NxPageHeader><NxAlert v-if="error||notice" :tone="error?'danger':'success'">{{error||notice}}</NxAlert><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><NxCard v-for="c in [['Open',summary.open_count,'New tickets'],['In Progress',summary.in_progress_count,'Currently handled'],['Waiting',summary.waiting_count,'Awaiting action'],['Resolved',summary.resolved_count,'Completed tickets']]" :key="String(c[0])"><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">{{c[0]}}</p><p class="mt-2 text-2xl font-bold">{{c[1]||0}}</p><p class="mt-1 text-xs text-[var(--nx-text-muted)]">{{c[2]}}</p></NxCard></section>
<NxToolbar><div class="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div><h2 class="font-bold">Ticket Queue</h2><p class="text-sm text-[var(--nx-text-muted)]">{{filtered.length}} matching tickets</p></div><div class="flex flex-col gap-2 sm:flex-row"><select v-model="statusFilter" :class="inputClass+' sm:w-60'"><option value="">All Statuses</option><option v-for="s in ['OPEN','IN_PROGRESS','WAITING_CUSTOMER','WAITING_TECHNICIAN','WAITING_CUSTOMER_SCHEDULE','VISIT_SCHEDULED','RESOLVED','CLOSED','CANCELLED']" :key="s">{{label(s)}}</option></select><input v-model="search" type="search" placeholder="Search ticket or subscriber…" :class="inputClass+' sm:w-80'"></div></div></NxToolbar>
<NxTableShell min-width="1050px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Ticket</th><th class="px-4 py-3">Subscriber</th><th class="px-4 py-3">Subject</th><th class="px-4 py-3">Priority</th><th class="px-4 py-3">Status</th><th class="px-4 py-3">Assigned</th><th class="px-4 py-3 text-right">Action</th></tr></thead><tbody><tr v-if="!filtered.length"><td colspan="7" class="px-4 py-12 text-center text-[var(--nx-text-muted)]">No tickets found.</td></tr><tr v-for="r in filtered" :key="r.id"><td class="px-4 py-3"><b class="font-mono">{{r.ticket_no||`#${r.id}`}}</b><small class="block text-[var(--nx-text-muted)]">{{fmt(r.created_at)}}</small></td><td class="px-4 py-3"><b>{{r.subscriber_name||'—'}}</b><small class="block text-[var(--nx-text-muted)]">{{r.account_number||'—'}}</small></td><td class="max-w-sm px-4 py-3"><b>{{r.subject||'—'}}</b><small class="block text-[var(--nx-text-muted)]">{{label(r.category)}}</small></td><td class="px-4 py-3"><NxBadge :tone="tone(r.priority)">{{r.priority||'—'}}</NxBadge></td><td class="px-4 py-3"><NxBadge :tone="tone(r.status)">{{label(r.status)}}</NxBadge></td><td class="px-4 py-3">{{r.assigned_user_name||r.assigned_username||'Waiting for personnel'}}</td><td class="px-4 py-3 text-right"><NxButton variant="secondary" :disabled="busy" @click="show(r)">Manage</NxButton></td></tr></tbody></NxTableShell>
<NxModal :open="open" :title="ticket.ticket_no||'Ticket Details'" :description="`${ticket.subscriber_name||'Subscriber'} · Created ${fmt(ticket.created_at)}`" max-width="76rem" @close="open=false"><div class="grid gap-4 p-5 xl:grid-cols-[minmax(0,2fr)_minmax(310px,1fr)]"><div class="space-y-4"><NxCard><div class="grid gap-4 md:grid-cols-2"><div class="md:col-span-2"><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">Subject</p><p class="mt-1 font-bold">{{ticket.subject||'—'}}</p></div><div><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">Category</p><p class="mt-1">{{label(ticket.category)}}</p></div><div><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">Preferred Visit</p><p class="mt-1">{{ticket.preferred_visit_date||ticket.preferred_schedule||'Not scheduled'}}</p></div><div class="md:col-span-2"><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">Description</p><p class="mt-1 whitespace-pre-wrap">{{ticket.description||'—'}}</p></div></div></NxCard><NxCard title="Conversation" :description="`${messages.length} messages`"><div class="max-h-[35vh] space-y-3 overflow-auto"><div v-for="m in messages" :key="m.id" class="rounded-md border border-[var(--nx-border)] p-3" :class="Number(m.is_internal)?'bg-amber-50 text-slate-900 dark:bg-amber-950/30 dark:text-slate-100':'bg-[var(--nx-surface-muted)]'"><div class="flex justify-between gap-3"><b>{{m.full_name||m.username||m.sender_type}}</b><small>{{fmt(m.created_at)}}</small></div><NxBadge v-if="Number(m.is_internal)" tone="warning">INTERNAL</NxBadge><p class="mt-2 whitespace-pre-wrap text-sm">{{m.message}}</p></div><p v-if="!messages.length" class="py-8 text-center text-[var(--nx-text-muted)]">No messages yet.</p></div></NxCard></div>
<div class="space-y-4"><NxCard title="Subscriber"><dl class="space-y-3 text-sm"><div><dt class="text-[var(--nx-text-muted)]">Name / Account</dt><dd class="font-semibold">{{ticket.subscriber_name||'—'}} · {{ticket.account_number||'—'}}</dd></div><div><dt class="text-[var(--nx-text-muted)]">Contact</dt><dd>{{ticket.email||'—'}}<br>{{ticket.contact_number||'—'}}</dd></div><div><dt class="text-[var(--nx-text-muted)]">Service</dt><dd>{{ticket.service_number||ticket.ppp_username||'—'}}</dd></div></dl></NxCard><NxCard title="Manage Ticket"><div class="space-y-3"><label class="grid gap-1 text-sm font-semibold">Assigned To<select v-model="assigned" :class="inputClass"><option value="0">Unassigned</option><option v-for="u in users" :key="u.id" :value="u.id">{{u.full_name||u.username}}</option></select></label><NxButton class="w-full" variant="secondary" :disabled="busy" @click="command('/api/v1/tickets/assign',{assigned_user_id:assigned},'Ticket assignment updated.')">Assign Ticket</NxButton><label class="grid gap-1 text-sm font-semibold">Status<select v-model="ticketStatus" :class="inputClass"><option v-for="s in ['OPEN','IN_PROGRESS','WAITING_CUSTOMER','WAITING_TECHNICIAN','WAITING_CUSTOMER_SCHEDULE','VISIT_SCHEDULED','RESOLVED','CLOSED','CANCELLED']" :key="s">{{label(s)}}</option></select></label><NxButton class="w-full" :disabled="busy" @click="command('/api/v1/tickets/status',{status:ticketStatus},'Ticket status updated.')">Update Status</NxButton><label class="grid gap-1 text-sm font-semibold">Priority<select v-model="priority" :class="inputClass"><option v-for="p in ['LOW','MEDIUM','HIGH','URGENT']" :key="p">{{p}}</option></select></label><NxButton class="w-full" variant="secondary" :disabled="busy" @click="command('/api/v1/tickets/priority',{priority},'Ticket priority updated.')">Update Priority</NxButton></div></NxCard></div></div>
<div class="grid gap-4 border-t border-[var(--nx-border)] p-5 lg:grid-cols-2"><form class="space-y-2" @submit.prevent="sendReply"><label class="text-sm font-semibold">Public Reply</label><textarea v-model="reply" rows="3" placeholder="Visible to the subscriber" :class="inputClass"></textarea><NxButton type="submit" :disabled="busy||!reply.trim()">Send Reply</NxButton></form><form class="space-y-2" @submit.prevent="addNote"><label class="text-sm font-semibold">Internal Note</label><textarea v-model="note" rows="3" placeholder="Staff-only note" :class="inputClass"></textarea><NxButton type="submit" variant="secondary" :disabled="busy||!note.trim()">Add Internal Note</NxButton></form></div><template #footer><NxButton variant="secondary" :disabled="busy" @click="requestSchedule">Request Schedule</NxButton><NxButton :disabled="busy" @click="createWorkOrder">Create Work Order</NxButton><NxButton variant="secondary" @click="open=false">Close</NxButton></template></NxModal></div></template>
<style scoped>:global([data-nx-next-root="tickets"]){max-width:100%;overflow-x:hidden}</style>
